3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\ValidatesShopifyWebhookHmac;
7	use App\Jobs\Shopify\ProcessShopifyOrderWebhookJob;
8	use App\Models\Core\Professional\ProfessionalIntegration;
9	use Illuminate\Http\JsonResponse;
10	use Illuminate\Http\Request;
11	use Illuminate\Support\Facades\Cache;
12	use Illuminate\Support\Facades\Log;
13	
14	// V2: Receives Shopify orders/paid webhooks. Validates HMAC signature, deduplicates, dispatches processing job.
15	class ShopifyOrderWebhookController extends ApiController
16	{
17	    use ValidatesShopifyWebhookHmac;
18	
19	    public function __invoke(Request $request): JsonResponse
20	    {
21	        $rawBody = (string) $request->getContent();
22	        $signature = (string) $request->header('X-Shopify-Hmac-SHA256', '');
23	        $webhookId = (string) $request->header('X-Shopify-Webhook-Id', '');
24	        $shopDomain = strtolower(trim((string) $request->header('X-Shopify-Shop-Domain', '')));
25	
26	        // Dedup read before HMAC: short-circuit already-processed IDs without recomputing the hash.
27	        $dedupeKey = $webhookId !== '' ? "shopify:webhook:order:{$webhookId}" : null;
28	        if ($dedupeKey && Cache::has($dedupeKey)) {
29	            return $this->success(['received' => true, 'duplicate' => true]);
30	        }
31	
32	        if (! $this->isValidShopifyHmac($rawBody, $signature)) {
33	            Log::warning('Shopify order webhook: invalid HMAC signature', [
34	                'shop_domain' => $shopDomain,
35	            ]);
36	
37	            return $this->error('invalid signature', 401);
38	        }
39	
40	        // Dedup write after HMAC passes: claim this ID to prevent concurrent double-dispatch.
41	        if ($dedupeKey && ! Cache::add($dedupeKey, true, now()->addHours(24))) {
42	            return $this->success(['received' => true, 'duplicate' => true]);
43	        }
44	
45	        $integration = ProfessionalIntegration::query()
46	            ->where('shopify_shop_domain', $shopDomain)
47	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
48	            ->first();
49	
50	        if (! $integration) {
51	            Log::warning('Shopify order webhook: unknown shop domain', [
52	                'shop_domain' => $shopDomain,
53	            ]);
54	
55	            return $this->success(['received' => true]);
56	        }
57	
58	        $payload = json_decode($rawBody, true);
59	        if (! is_array($payload)) {
60	            Log::warning('Shopify order webhook: invalid JSON payload', [
61	                'shop_domain' => $shopDomain,
62	            ]);
63	
64	            return $this->success(['received' => true]);
65	        }
66	
67	        ProcessShopifyOrderWebhookJob::dispatch(
68	            (string) $integration->professional_id,
69	            $payload
70	        );
71	
72	        return $this->success(['received' => true]);
73	    }
74	}
