3	namespace App\Http\Controllers\Concerns;
4	
5	// V2: Validates Shopify webhook HMAC-SHA256 signatures against primary and fallback secrets for secure webhook ingestion.
6	trait ValidatesShopifyWebhookHmac
7	{
8	    protected function isValidShopifyHmac(string $rawBody, string $signature): bool
9	    {
10	        if ($signature === '') {
11	            return false;
12	        }
13	
14	        $secrets = array_filter([
15	            (string) config('services.shopify.webhook_secret'),
16	            (string) config('services.shopify.fallback_secret'),
17	        ], static fn (string $s): bool => $s !== '');
18	
19	        foreach ($secrets as $secret) {
20	            $expected = base64_encode(hash_hmac('sha256', $rawBody, $secret, true));
21	            if (hash_equals($expected, $signature)) {
22	                return true;
23	            }
24	        }
25	
26	        return false;
27	    }
28	}
