11	
12	// Verifies a Shopify session token (JWT) sent by an admin UI extension.
13	//
14	// Shopify-issued session tokens are HS256-signed with the app's API secret.
15	// They embed the destination shop in the `dest` claim, the app's client ID
16	// in the `aud` claim, and short expiry (~60s) in `exp`. We verify all three
17	// before resolving the brand professional from the shop domain — same shape
18	// the embedded-key middleware exposes downstream so controllers can be auth-
19	// agnostic.
20	//
21	// Docs: https://shopify.dev/docs/apps/build/authentication-authorization/session-tokens
22	class VerifyShopifySessionToken
23	{
24	    public function __construct(
25	        private readonly ShopifyShopResolver $resolver,
26	    ) {}
27	
28	    public function handle(Request $request, Closure $next): Response
29	    {
30	        $secret = (string) config('services.shopify.api_secret');
31	        $expectedAud = (string) config('services.shopify.api_key');
32	
33	        if ($secret === '' || $expectedAud === '') {
34	            return response()->json([
35	                'message' => 'Shopify session-token verification is not configured on this server.',
36	            ], 500);
37	        }
38	
39	        $token = (string) str_replace('Bearer ', '', $request->header('Authorization', ''));
40	
41	        if ($token === '') {
42	            return response()->json(['message' => 'Missing session token.'], 401);
43	        }
44	
45	        try {
46	            $claims = (array) JWT::decode($token, new Key($secret, 'HS256'));
47	        } catch (\Throwable $e) {
48	            return response()->json(['message' => 'Invalid session token.'], 401);
49	        }
50	
51	        // Audience must match this app's client ID — guards against tokens
52	        // issued for a different Shopify app being replayed against ours.
53	        $aud = (string) ($claims['aud'] ?? '');
54	        if (! hash_equals($expectedAud, $aud)) {
55	            return response()->json(['message' => 'Session token audience mismatch.'], 401);
56	        }
57	
58	        // Pull the shop domain out of the `dest` claim and normalise.
59	        // Shape: https://{shop}.myshopify.com (no path).
60	        $dest = (string) ($claims['dest'] ?? '');
61	        $shopDomain = strtolower(parse_url($dest, PHP_URL_HOST) ?? '');
62	
63	        if ($shopDomain === '' || ! str_ends_with($shopDomain, '.myshopify.com')) {
64	            return response()->json(['message' => 'Invalid session token destination.'], 401);
65	        }
66	
67	        $professionalId = $this->resolver->resolveProfessionalId($shopDomain);
68	
69	        if ($professionalId === null) {
70	            return response()->json([
71	                'error' => 'shop_not_connected',
72	                'message' => 'No Side St account is linked to this Shopify store.',
73	            ], 404);
74	        }
75	
76	        // Match the attribute name used by VerifyEmbeddedApiKey so controllers
77	        // can be reused regardless of which auth path got them here.
78	        $request->attributes->set('embedded_professional_id', $professionalId);
79	
80	        return $next($request);
81	    }
82	}
